import { SUPPORTED_HASH } from './assertHash.mjs'

// this returns null on unsupported types to fall back to noble impl
export function toWebCryptoDigestType(type) {
  // There are implemented via Web Crypto API
  if (type === 'sha256') return 'SHA-256'
  if (type === 'sha384') return 'SHA-384'
  if (type === 'sha512') return 'SHA-512'

  if (type === 'sha3-256' || type === 'sha3-384' || type === 'sha3-512') {
    // TODO: enable this when https://twiss.github.io/webcrypto-modern-algos/ lands (sha3 / supports)
    // Node.js tracking: https://github.com/nodejs/node/pull/57270
    /*
    if (!globalThis.crypto?.supports) return null
    const upper = type.toUpperCase()
    return globalThis.crypto.supports('digest', upper) ? upper : null
    */
    return null
  }

  // Returning null means that these algos are allowed (do not throw here), but are implemented via fallback/manually
  // This will cause the wrapper to call *Sync version, which will re-verify everything and use noble-based version
  if (SUPPORTED_HASH.includes(type)) return null

  throw new Error('Unexpected hash type')
}
